// @ai-proposed SAT-0 — generated by the verify-feature skill.
package com.example.intake;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.hamcrest.Matchers.matchesPattern;

import com.jayway.jsonpath.JsonPath;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class IntakeApiTest {

    @Autowired
    MockMvc mvc;

    private static String body(String name, String type, String description) {
        return "{\"clientName\":\"" + name + "\",\"projectType\":\"" + type + "\",\"description\":\"" + description + "\"}";
    }

    private org.springframework.test.web.servlet.ResultActions submit(String json) throws Exception {
        return mvc.perform(post("/api/intakes").contentType(MediaType.APPLICATION_JSON).content(json));
    }

    @Test
    @DisplayName("SAT-0 AC-1 valid intake returns 201 with an INT- reference and status RECEIVED")
    void validIntakeIsReceived() throws Exception {
        for (String type : new String[] {"ECOMMERCE", "WEBSITE", "API"}) {
            submit(body("Ada", type, "A storefront for handmade ceramics with a cart"))
                    .andExpect(status().isCreated())
                    .andExpect(jsonPath("$.reference", matchesPattern("INT-\\d{4,}")))
                    .andExpect(jsonPath("$.status").value("RECEIVED"));
        }
    }

    @Test
    @DisplayName("SAT-0 AC-2 description under 20 characters returns 400 with the message")
    void shortDescriptionIsRejected() throws Exception {
        submit(body("Ada", "WEBSITE", "too short, 19 chars"))   // exactly 19 characters
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.error").value("Describe what you want in at least 20 characters"));
        submit(body("Ada", "WEBSITE", "exactly twenty chars"))  // boundary: 20 characters is accepted
                .andExpect(status().isCreated());
    }

    @Test
    @DisplayName("SAT-0 AC-3 a submitted intake reads back by reference and an unknown one is 404")
    void readBack() throws Exception {
        String created = submit(body("Grace", "API", "An API that turns tickets into intents"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String ref = JsonPath.read(created, "$.reference");
        mvc.perform(get("/api/intakes/" + ref))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.reference").value(ref))
                .andExpect(jsonPath("$.clientName").value("Grace"))
                .andExpect(jsonPath("$.projectType").value("API"));
        mvc.perform(get("/api/intakes/INT-999999")).andExpect(status().isNotFound());
    }
}
